import { expect } from '@skyramp/skyramp';

export async function signIn(page, email, password) {
    await page.getByRole("textbox", { name: "Email" }).fill(email);
    await page.getByRole("textbox", { name: "Password" }).fill(password);
    // Wait to finish any potential hydration
    await page.waitForTimeout(1500);
    const responsePromise = page.waitForResponse("**/auth/login**");
    await page.getByRole("button", { name: "Sign In" }).click();
    return await responsePromise;
}

export async function dismissProjectOwnerReminder(page) {
    await page.getByRole("button", { name: "Remind Later" }).click();
}

export async function openExportDrawer(page) {
    await page.getByRole("button", { name: "import_export Import / Export" }).click();
    await page.getByRole("button", { name: "Export Items" }).click();
    await expect(page.getByRole("button", { name: "chevron_right Advanced Options" })).toBeVisible();
}

export async function expandAdvancedOptions(page) {
    await page.getByRole("button", { name: "chevron_right Advanced Options" }).click();
}

export async function collapseAdvancedOptions(page) {
    await page.getByRole("button", { name: "expand_more Advanced Options" }).click();
}

export async function fillExportFullTextSearch(page, searchTerm) {
    await page.getByRole("textbox", { name: "Search" }).fill(searchTerm);
}

export async function readAdvancedFieldLayout(page) {
    return await page.evaluate(() => {
        const fieldBox = (label: string) => {
            const labels = Array.from(document.querySelectorAll(".export-fields p.type-label"));
            const heading = labels.find((el) => el.textContent?.trim() === label);
            const field = heading?.closest(".field");
            if (!field) return null;
            const rect = field.getBoundingClientRect();
            return { top: Math.round(rect.top), left: Math.round(rect.left) };
        };
        return { sortField: fieldBox("Sort Field"), sortDirection: fieldBox("Sort Direction") };
    });
}
